WITH Base AS (SELECT *, CASE WHEN units >= 40 THEN 'High' WHEN units >= 15 THEN 'Medium' ELSE 'Low' END AS units_level FROM store_sales WHERE (revenue > 1100 AND store_id IN (4, 5)) OR product_id IN (1, 5, 7, 10)), StoreIdSummary AS (SELECT store_id, CASE WHEN units >= 31 THEN 'high' WHEN units >= 12 THEN 'mid' ELSE 'low' END AS units_bucket, COUNT(*) AS row_count FROM Base GROUP BY store_id, CASE WHEN units >= 31 THEN 'high' WHEN units >= 12 THEN 'mid' ELSE 'low' END) SELECT * FROM StoreIdSummary WHERE row_count >= 4 ORDER BY store_id, row_count DESC, units_bucket LIMIT 20
